#include <ctype.h>
#include <errno.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct{const char*name;char count[64],scope[16],running[32];int seen,valid;unsigned long long value;} Event;
static Event events[]={{"cycles","NA","NA","NA",0,0,0},{"instructions","NA","NA","NA",0,0,0},{"cache-misses","NA","NA","NA",0,0,0}};
static int exists(const char*p){FILE*f=fopen(p,"rb");if(!f)return 0;fclose(f);return 1;}
static size_t split(char*s,char**v,size_t cap){size_t n=0;v[n++]=s;for(char*p=s;*p;p++)if(*p==','){*p=0;if(n<cap)v[n++]=p+1;}return n;}
static int count_value(const char*s,unsigned long long*out){while(isspace((unsigned char)*s))s++;if(!*s||*s=='<'||strstr(s,"not supported")||strstr(s,"not counted"))return 0;char*e;errno=0;unsigned long long v=strtoull(s,&e,10);if(errno||e==s)return 0;while(*e==' '||*e=='\t')e++;if(*e=='.'){e++;if(!*e)return 0;while(*e=='0')e++;}if(*e)return 0;*out=v;return 1;}
static int percent_value(const char*s,char*out,size_t cap){while(isspace((unsigned char)*s))s++;if(!*s)return 0;char*e;errno=0;double v=strtod(s,&e);if(errno||e==s||!isfinite(v)||v<0||v>100)return 0;while(isspace((unsigned char)*e))e++;if(*e)return 0;snprintf(out,cap,"%.6g",v);return 1;}
static int known_event(const char*s){size_t n=strcspn(s,":");for(size_t i=0;i<sizeof events/sizeof events[0];i++)if(strlen(events[i].name)==n&&!strncmp(s,events[i].name,n))return 1;return 0;}
static void note(FILE*f,unsigned long line,const char*m,const char*raw){fprintf(f,"line %lu: %s: %s\n",line,m,raw);}
int main(int argc,char**argv){if(argc!=3){fprintf(stderr,"Usage: %s PERF_RAW.csv SUMMARY.csv\n",argv[0]);return 2;}char notespath[4096];if(strlen(argv[2])+11>=sizeof notespath){fputs("perf summary path too long\n",stderr);return 2;}strcpy(notespath,argv[2]);char*dot=strrchr(notespath,'.');if(dot)strcpy(dot,".notes.txt");else strcat(notespath,".notes.txt");if(exists(argv[2])||exists(notespath)){fputs("perf summary refuses to overwrite existing derived outputs\n",stderr);return 2;}FILE*in=fopen(argv[1],"rb");if(!in){perror(argv[1]);return 2;}FILE*notes=fopen(notespath,"wb");if(!notes){perror(notespath);fclose(in);return 2;}char line[4096];unsigned long ln=0;int diagnostics=0;while(fgets(line,sizeof line,in)){ln++;size_t len=strlen(line);if(len&&line[len-1]=='\n')line[--len]=0;if(len&&line[len-1]=='\r')line[--len]=0;if(len==sizeof line-1&&!feof(in)){note(notes,ln,"truncated row",line);diagnostics++;int c;while((c=fgetc(in))!=EOF&&c!='\n'){}continue;}if(!len||line[0]=='#')continue;char lower[4096];for(size_t i=0;i<=len;i++)lower[i]=(char)tolower((unsigned char)line[i]);if(strstr(lower,"permission")||strstr(lower,"not permitted")||strstr(lower,"not supported")||strstr(lower,"error:")){note(notes,ln,"perf diagnostic",line);diagnostics++;}char copy[4096];memcpy(copy,line,len+1);char*fields[32];size_t n=split(copy,fields,32);if(n<3){note(notes,ln,"malformed row (expected value,unit,event,...)",line);diagnostics++;continue;}const char*raw_event=fields[2];char ev[64],scope[16]="all";size_t en=strcspn(raw_event,":");if(en>=sizeof ev){note(notes,ln,"event name too long",line);diagnostics++;continue;}memcpy(ev,raw_event,en);ev[en]=0;if(en<strlen(raw_event)){const char*suf=raw_event+en+1;if(!strcmp(suf,"u"))strcpy(scope,"user");else if(!strcmp(suf,"k"))strcpy(scope,"kernel");else snprintf(scope,sizeof scope,"%.15s",suf);}
 int index=-1;for(size_t i=0;i<sizeof events/sizeof events[0];i++)if(!strcmp(ev,events[i].name)){index=(int)i;break;}if(index<0){for(size_t j=0;j<n;j++)if(known_event(fields[j])){note(notes,ln,"malformed perf row; recognized event shifted from field three (locale/delimiter?)",line);diagnostics++;goto next_row;}continue;}if(n!=5){note(notes,ln,"malformed perf row/delimiter (expected five fields)",line);diagnostics++;continue;}if(events[index].seen){note(notes,ln,"duplicate event",raw_event);diagnostics++;continue;}events[index].seen=1;snprintf(events[index].scope,sizeof events[index].scope,"%s",scope);if(count_value(fields[0],&events[index].value)){events[index].valid=1;snprintf(events[index].count,sizeof events[index].count,"%llu",events[index].value);}else{snprintf(events[index].count,sizeof events[index].count,"NA");note(notes,ln,"counter unavailable or malformed",fields[0]);diagnostics++;}if(percent_value(fields[4],events[index].running,sizeof events[index].running)==0){snprintf(events[index].running,sizeof events[index].running,"NA");note(notes,ln,"running percentage unavailable or malformed",fields[4]);diagnostics++;}next_row:;}
 if(ferror(in)){perror(argv[1]);fclose(in);fclose(notes);return 3;}fclose(in);for(size_t i=0;i<3;i++)if(!events[i].seen){note(notes,0,"counter row missing; value unavailable",events[i].name);diagnostics++;}fprintf(notes,"diagnostic_rows=%d\n",diagnostics);fclose(notes);FILE*out=fopen(argv[2],"wb");if(!out){perror(argv[2]);return 3;}fprintf(out,"event,count,scope,running_percent\n");for(size_t i=0;i<3;i++)fprintf(out,"%s,%s,%s,%s\n",events[i].name,events[i].count,events[i].scope,events[i].running);fprintf(out,"ipc,");int ci=-1,ii=-1;for(int i=0;i<3;i++){if(!strcmp(events[i].name,"cycles"))ci=i;if(!strcmp(events[i].name,"instructions"))ii=i;}if(ci>=0&&ii>=0&&events[ci].valid&&events[ii].valid&&events[ci].value&&strcmp(events[ci].scope,events[ii].scope)==0)fprintf(out,"%.9g,%s,NA\n",(double)events[ii].value/(double)events[ci].value,events[ci].scope);else fputs("NA,NA,NA\n",out);if(fclose(out)){perror(argv[2]);return 3;}printf("perf summary written: %s\nnotes: %s\n",argv[2],notespath);return 0;}
